use client;

import { useState, useEffect } from 'react';
import ThemeLabStage from './stage';

const THEMES = [
  {
    id: 'navy-sharp',
    name: 'Navy Sharp',
    vars: {
      '--tl-bg': '#1a1a2e',
      '--tl-bg-2': '#282842',
      '--tl-surface': '#333350',
      '--tl-line': '#444466',
      '--tl-text': '#ffffff',
      '--tl-text-dim': '#888899',
      '--tl-accent': '#ff0000',
      '--tl-accent-2': '#ff5500',
      '--tl-accent-soft': '#ff8800',
      '--tl-glow': '#ffcc00',
      '--tl-petal': '#ff6600',
    },
  },
  {
    id: 'evening-warm',
    name: 'Evening Warm',
    vars: {
      '--tl-bg': '#1a1a2e',
      '--tl-bg-2': '#282842',
      '--tl-surface': '#333350',
      '--tl-line': '#444466',
      '--tl-text': '#ffffff',
      '--tl-text-dim': '#888899',
      '--tl-accent': '#ff6600',
      '--tl-accent-2': '#ff8800',
      '--tl-accent-soft': '#ffcc00',
      '--tl-glow': '#ffcc00',
      '--tl-petal': '#ff6600',
    },
  },
  {
    id: 'pitwall',
    name: 'Pitwall',
    vars: {
      '--tl-bg': '#000000',
      '--tl-bg-2': '#1a1a2e',
      '--tl-surface': '#333350',
      '--tl-line': '#444466',
      '--tl-text': '#ffffff',
      '--tl-text-dim': '#888899',
      '--tl-accent': '#ff0000',
      '--tl-accent-2': '#ff5500',
      '--tl-accent-soft': '#ff8800',
      '--tl-glow': '#ffcc00',
      '--tl-petal': '#ff6600',
    },
  },
  {
    id: 'dusk-calm',
    name: 'Dusk Calm',
    vars: {
      '--tl-bg': '#1a1a2e',
      '--tl-bg-2': '#282842',
      '--tl-surface': '#333350',
      '--tl-line': '#444466',
      '--tl-text': '#ffffff',
      '--tl-text-dim': '#888899',
      '--tl-accent': '#ff6600',
      '--tl-accent-2': '#ff8800',
      '--tl-accent-soft': '#ffcc00',
      '--tl-glow': '#ffcc00',
      '--tl-petal': '#ff6600',
    },
  },
];

const ThemeLab = () => {
  const [idx, setIdx] = useState(0);

  useEffect(() => {
    const hash = location.hash.slice(1);
    const themeIndex = THEMES.findIndex((theme) => theme.id === hash);
    if (themeIndex !== -1) {
      setIdx(themeIndex);
    }
  }, []);

  useEffect(() => {
    location.hash = THEMES[idx].id;
  }, [idx]);

  return (
    <div
      style={{
        ...THEMES[idx].vars,
        background: 'var(--tl-bg)',
        color: 'var(--tl-text)',
        minHeight: '100dvh',
      }}
    >
      <ThemeLabStage />
      <div
        style={{
          position: 'fixed',
          bottom: '0',
          left: '50%',
          transform: 'translateX(-50%)',
          display: 'flex',
          gap: '10px',
          padding: '10px',
          background: 'var(--tl-surface)',
          border: '1px solid var(--tl-line)',
        }}
      >
        {THEMES.map((theme, i) => (
          <button
            key={theme.id}
            onClick={() => setIdx(i)}
            style={{
              background: idx === i ? 'var(--tl-accent)' : 'transparent',
              color: idx === i ? 'var(--tl-glow)' : 'var(--tl-text)',
              border: 'none',
              padding: '5px 10px',
              cursor: 'pointer',
            }}
          >
            {theme.name}
          </button>
        ))}
      </div>
    </div>
  );
};

export default ThemeLab;
